window.fetchStoreQuotes = async function() {
    try {
        const res = await fetch(`${API}/store/quotes/${currentGroup.id}`);
        const data = await res.json();
        
        const list = getEl('store-quotes-list');
        
        if (!data || !data.success || !data.quotes || data.quotes.length === 0) {
            if (!window.storeQuotesCache || window.storeQuotesCache.length === 0) {
                window.storeQuotesCache = []; 
            }
            window.renderStoreQuotes();
            return;
        }

        const fetchedQuotes = data.quotes;
        if (!window.storeQuotesCache) window.storeQuotesCache = [];
        
        fetchedQuotes.forEach(fq => {
            if (!window.storeQuotesCache.find(q => q.id === fq.id)) {
                window.storeQuotesCache.push(fq);
            }
        });
        
        window.renderStoreQuotes();
    } catch(e) {
        console.error(e);
    }
};

window.renderStoreQuotes = function() {
    const list = document.getElementById('store-quotes-list');
    if(!list) return;

    if (!document.getElementById('quotes-search-bar')) {
        list.insertAdjacentHTML('beforebegin', `
            <div id="quotes-search-bar" class="flex flex-col sm:flex-row gap-2 mb-4">
                <div class="relative flex-1">
                    <i class="fa-solid fa-magnifying-glass absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
                    <input type="text" id="quote-search-input" oninput="window.renderStoreQuotes()" placeholder="חיפוש לקוח, טלפון או מס' הצעה..." class="w-full bg-slate-50 border border-slate-200 rounded-xl py-2.5 pr-10 pl-4 text-sm font-bold shadow-sm outline-none focus:border-indigo-400 transition">
                </div>
                <select id="quote-status-filter" onchange="window.renderStoreQuotes()" class="modern-input py-2.5 px-3 text-sm font-bold bg-slate-50 border-slate-200 text-slate-700 rounded-xl w-full sm:w-auto outline-none focus:border-indigo-400">
                    <option value="all">כל הסטטוסים</option>
                    <option value="draft">טיוטות והצעות חדשות</option>
                    <option value="sent">נשלחו ללקוח</option>
                    <option value="approved">אושרו (הפכו להזמנות)</option>
                </select>
            </div>
        `);
    }

    if(!window.storeQuotesCache || window.storeQuotesCache.length === 0) {
        list.innerHTML = '<p class="text-center text-slate-400 py-8 bg-slate-50 rounded-2xl border border-dashed border-slate-200">טרם הופקו הצעות מחיר במערכת.</p>';
        return;
    }

    const searchQuery = (document.getElementById('quote-search-input')?.value || '').toLowerCase();
    const statusFilter = document.getElementById('quote-status-filter')?.value || 'all';

    let filteredQuotes = window.storeQuotesCache.filter(q => {
        const matchSearch = String(q.id).includes(searchQuery) || (q.quote_number && q.quote_number.toLowerCase().includes(searchQuery)) || (q.customer_name && q.customer_name.toLowerCase().includes(searchQuery)) || (q.customer_phone && q.customer_phone.includes(searchQuery));
        
        let qStatusRaw = q.quote_status || q.status;
        if (qStatusRaw === 'new' || qStatusRaw === 'quote') qStatusRaw = 'draft';
        if (qStatusRaw === 'waiting_customer') qStatusRaw = 'sent'; 
        if (qStatusRaw === 'customer_approved') qStatusRaw = 'approved'; 
        
        const matchStatus = statusFilter === 'all' || qStatusRaw === statusFilter;
        
        return matchSearch && matchStatus;
    });

    filteredQuotes.sort((a,b) => new Date(b.created_at) - new Date(a.created_at));

    if(filteredQuotes.length === 0) {
        list.innerHTML = '<p class="text-center text-slate-400 py-8 bg-slate-50 rounded-2xl border border-dashed border-slate-200">לא נמצאו הצעות מחיר התואמות לחיפוש.</p>';
        return;
    }

    const statuses = {
        'draft': 'טיוטה (טרם נשלחה)',
        'sent': 'נשלחה ללקוח',
        'customer_approved': 'אישור לקוח (העבר להזמנות)',
        'frozen': 'הוקפאה / הושהתה',
        'cancelled': 'בוטלה ע"י הלקוח',
        'approved': 'אושרה בהצלחה'
    };

    let html = '';
    
    filteredQuotes.forEach(q => {
        try {
            let currentStatus = q.quote_status || q.status;
            if (currentStatus === 'new' || currentStatus === 'quote') currentStatus = 'draft';
            if (currentStatus === 'waiting_customer') currentStatus = 'sent';
            
            const isApproved = (currentStatus === 'approved' || currentStatus === 'customer_approved');
            const optionsHtml = Object.keys(statuses).map(k => `<option value="${k}" ${currentStatus === k ? 'selected' : ''}>${statuses[k]}</option>`).join('');
            
            const totalAmount = q.total_amount ? parseFloat(q.total_amount).toFixed(2) : "0.00";
            const dateStr = q.created_at ? new Date(q.created_at).toLocaleDateString('he-IL', {hour:'2-digit', minute:'2-digit'}) : "תאריך לא ידוע";
            
            let internalNote = '';
            let customerNote = '';
            try {
                const rawItems = Array.isArray(q.items) ? q.items : (typeof q.items === 'string' ? JSON.parse(q.items || '[]') : []);
                const metaItem = rawItems.find(i => i.is_quote_metadata);
                if (metaItem) {
                    const parsedMeta = JSON.parse(metaItem.data);
                    if (parsedMeta.internalNote) internalNote = parsedMeta.internalNote;
                    if (parsedMeta.customerNote) customerNote = parsedMeta.customerNote;
                }
            } catch(e){}

            if (!internalNote && q.notes) {
                if (q.notes.includes('הערות לקוח:')) {
                    customerNote = q.notes.replace('הערות לקוח:', '').trim();
                } else {
                    try {
                        const parsedNotes = JSON.parse(q.notes);
                        if (parsedNotes.internalNote) internalNote = parsedNotes.internalNote;
                        if (parsedNotes.notes && parsedNotes.notes.includes('הערות לקוח:')) customerNote = parsedNotes.notes.replace('הערות לקוח:', '').trim();
                    } catch(e) {
                        internalNote = q.notes;
                    }
                }
            }
            internalNote = internalNote.replace('[הצעת מחיר] - הוגשה בקשה לאירוע/פרויקט.', '').trim();
            
            let displayNote = '';
            if(internalNote) {
                displayNote += `<div class="mt-2 bg-amber-50 p-2.5 rounded-lg text-xs font-bold text-amber-800 border border-amber-200 shadow-sm"><i class="fa-solid fa-lock mr-1"></i> עסק: ${safeStr(internalNote)}</div>`;
            }
            if (customerNote) {
                displayNote += `<div class="mt-2 bg-indigo-50 p-2.5 rounded-lg text-xs font-bold text-indigo-800 border border-indigo-200 shadow-sm"><i class="fa-regular fa-comment-dots mr-1"></i> לקוח: ${safeStr(customerNote)}</div>`;
            }

            let approveBtnHtml = '';
            let cardStyle = 'border-slate-200 shadow-sm bg-white hover:shadow-md hover:border-indigo-300';
            
            if (isApproved) {
                 cardStyle = 'border-2 border-green-500 bg-green-50/40 shadow-md';
                 approveBtnHtml = `<span class="text-[11px] font-black text-green-700 flex items-center gap-1.5 mt-2 w-full justify-center bg-green-100 py-2 rounded-lg border border-green-300 shadow-sm"><i class="fa-solid fa-check-circle text-sm"></i> עברה לתור הזמנות</span>`;
            } else {
                 approveBtnHtml = `<button onclick="window.approveQuoteToOrder(${q.id})" class="bg-slate-800 text-white px-3 py-2 rounded-lg text-[10px] font-bold shadow-md hover:bg-slate-700 transition flex items-center gap-1.5 w-full justify-center mt-2"><i class="fa-solid fa-check"></i> אישור והעברה להזמנות</button>`;
            }

            html += `
            <div class="p-4 rounded-2xl border ${cardStyle} flex flex-col mb-3 transition-all">
                <div class="flex justify-between items-start mb-3">
                    <div class="flex-1 min-w-0">
                        <h4 class="font-bold text-slate-800 text-sm truncate">${q.quote_number || `הצעה #${q.id}`} — ${safeStr(q.customer_name || 'לקוח ללא שם')}</h4>
                        <p class="text-lg font-black text-indigo-600 mt-0.5">₪${totalAmount}</p>
                        <p class="text-[10px] text-slate-500 mt-1"><i class="fa-regular fa-calendar mr-1"></i>${dateStr} | ${safeStr(q.customer_phone || 'ללא טלפון')}</p>
                        ${displayNote}
                    </div>
                    <div class="flex flex-col items-end gap-1 shrink-0">
                        <select id="quote-sel-${q.id}" onchange="window.updateQuoteStatus(${q.id}, this.value)" class="modern-input py-1 px-2 text-[10px] font-bold ${isApproved ? 'bg-green-100 text-green-800 border-green-300' : 'bg-slate-50 border-slate-200 text-slate-600'} rounded-lg shadow-sm focus:border-indigo-400" style="width:140px;" ${isApproved ? 'disabled' : ''}>
                            ${optionsHtml}
                        </select>
                        ${approveBtnHtml}
                    </div>
                </div>
                <div class="flex gap-2 border-t ${isApproved ? 'border-green-200' : 'border-slate-100'} pt-3 mt-1">
                    <button onclick="window.openEditQuoteModal(${q.id})" class="flex-1 bg-white text-slate-600 hover:text-indigo-600 hover:bg-indigo-50 py-2 rounded-xl text-xs font-bold transition shadow-sm border border-slate-200"><i class="fa-solid fa-pen"></i> ערוך</button>
                    <button onclick="window.sendQuoteToCustomer(${q.id})" class="flex-[1.5] bg-[#25D366] text-white hover:bg-[#1ebd58] py-2 rounded-xl text-xs font-bold transition shadow-sm flex items-center justify-center gap-1"><i class="fa-brands fa-whatsapp text-sm"></i> שליחה לאישור</button>
                    <button onclick="window.openQuotePreview(${q.id})" class="flex-[0.5] bg-white text-slate-600 hover:text-red-600 hover:bg-red-50 py-2 rounded-xl text-xs font-bold transition shadow-sm border border-slate-200" title="מסמך PDF"><i class="fa-solid fa-file-pdf"></i></button>
                </div>
            </div>`;
        } catch(err) {}
    });
    
    list.innerHTML = html;
};

window.updateQuoteStatus = async function(id, status) {
    if (status === 'approved' || status === 'customer_approved') {
        const selectEl = document.getElementById(`quote-sel-${id}`);
        if(selectEl) {
            const q = window.storeQuotesCache.find(x => String(x.id) === String(id));
            selectEl.value = q ? (q.quote_status || q.status) : 'draft'; 
        }
        window.approveQuoteToOrder(id);
        return;
    }

    try {
        const q = window.storeQuotesCache.find(x => String(x.id) === String(id));
        let isEmbeddedOrder = false;
        
        if (q) {
            if (q.status === 'new' || q.status === 'quote' || q.orderType === 'quote' || q.order_type === 'quote' || (q.notes && q.notes.includes('[הצעת מחיר]'))) {
                isEmbeddedOrder = true;
            }
        }

        if (isEmbeddedOrder) {
            await fetch(`${API}/store/orders/status`, {
                method: 'POST', headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ orderId: id, status: status })
            });
        } else {
            await fetch(`${API}/store/quotes/${id}/status`, {
                method: 'PATCH', headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ quoteStatus: status })
            });
        }

        if (q) {
            q.quote_status = status;
            q.status = status;
        }

        showToast('success', 'סטטוס הצעת המחיר עודכן');
        window.renderStoreQuotes();
    } catch(e) { showToast('error', 'שגיאת רשת בעדכון סטטוס'); }
};

window.sendQuoteToCustomer = function(id) {
    const q = window.storeQuotesCache.find(x => String(x.id) === String(id));
    if (!q) return;

    if (!q.customer_phone) {
        return showToast('error', 'לא מוגדר מספר טלפון ללקוח בהצעת מחיר זו.');
    }

    const storeAlias = document.getElementById('store-alias-input') ? document.getElementById('store-alias-input').value : '';
    const displayId = storeAlias || currentGroup.group_code;
    const publicUrl = `${window.location.origin}/${displayId}`;
    
    const cleanPhone = q.customer_phone.replace(/\D/g, '');
    let waPhone = cleanPhone;
    if (cleanPhone.startsWith('0')) {
        waPhone = '972' + cleanPhone.substring(1);
    }
    
    const amount = q.total_amount ? parseFloat(q.total_amount).toFixed(2) : "0.00";
    
    let text = `שלום ${safeStr(q.customer_name)}, בהמשך לפנייתך,\n`;
    text += `הכנו עבורך הצעת מחיר (מס' ${q.id}) על סך ₪${amount}.\n\n`;
    text += `ההצעה המלאה תצורף לכאן כמסמך PDF.\n`;
    text += `לצפייה במוצרים נוספים בחנות שלנו:\n${publicUrl}\n\n`;
    text += `אנא השב/י להודעה זו במילה "מאשר" או "לא מאשר" כדי שנוכל להתקדם.\n\n`;
    text += `בברכה,\n${currentGroup.name}\n\n`;
    text += `Oneflowlife.co.il תכירו, המערכת המושלמת לניהול משפחות ועסקים.`;

    window.updateQuoteStatus(q.id, 'sent');
    window.open(`https://wa.me/${waPhone}?text=${encodeURIComponent(text)}`, '_blank');
};

window.currentActionTargetId = null;
window.currentActionType = null; 

window.approveQuoteToOrder = function(id) {
    window.currentActionTargetId = id;
    window.currentActionType = 'quote';
    getEl('target-datetime-input').value = '';
    getEl('target-date-modal-title').innerText = 'המרה להזמנה';
    getEl('target-date-modal-desc').innerText = 'ההצעה תעבור לתור ההזמנות (וישובץ אירוע ביומן במידת הצורך). בחר תאריך ושעת יעד לאספקה/הגעה:';
    getEl('target-datetime-modal').classList.remove('hidden');
};

window.editOrderTargetDate = async function(orderId, currentDate) {
    window.currentActionTargetId = orderId;
    window.currentActionType = 'order';
    let formattedDate = '';
    if (currentDate && currentDate !== 'null' && currentDate !== '') {
        try {
            const d = new Date(currentDate);
            formattedDate = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0,16);
        } catch(e) {}
    }
    getEl('target-datetime-input').value = formattedDate;
    getEl('target-date-modal-title').innerText = 'עדכון יעד אספקה';
    getEl('target-date-modal-desc').innerText = 'בחר תאריך ושעה מעודכנים ליעד מסירת ההזמנה ללקוח:';
    getEl('target-datetime-modal').classList.remove('hidden');
};

window.submitTargetDatetime = async function() {
    const targetDate = document.getElementById('target-datetime-input').value;
    if (!targetDate && window.currentActionType === 'quote') {
        if (!confirm('לא הוזן תאריך יעד לאירוע/לאספקה. האם להמשיך ללא שיבוץ ביומן?')) return;
    }

    const btn = document.getElementById('btn-submit-target-date');
    btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> מאשר וממיר...';
    
    try {
        if (window.currentActionType === 'quote') {
            const q = window.storeQuotesCache.find(x => String(x.id) === String(window.currentActionTargetId));
            
            let approvalSuccess = false;

            // נעדכן את הסטטוס הראשי של ההזמנה בשרת כדי שתעבור למסך ההזמנות הפעילות
            try {
                const res = await fetch(`${API}/store/orders/status`, {
                    method: 'POST', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ orderId: window.currentActionTargetId, status: 'processing' })
                });
                const data = await res.json();
                if (data.success) approvalSuccess = true;
            } catch(e) {}

            // במקביל, נעדכן ספציפית את סטטוס ההצעה ל"אושרה"
            try {
                await fetch(`${API}/store/quotes/${window.currentActionTargetId}/status`, {
                    method: 'PATCH', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ quoteStatus: 'approved' })
                });
                approvalSuccess = true;
            } catch(e) {}

            if (!approvalSuccess) {
                throw new Error('שגיאה באישור ההצעה מול השרת.');
            }

            if (targetDate) {
                const d = new Date(targetDate);
                
                // שיבוץ אירוע ביומן
                const payload = {
                    groupId: currentGroup.id,
                    title: `ביצוע פרויקט/אירוע: ${q ? safeStr(q.customer_name) : ''}`,
                    eventDate: d.toISOString().split('T')[0],
                    startTime: d.toTimeString().substring(0,5),
                    serviceId: null,
                    notes: `ORDER_REF:${window.currentActionTargetId}`,
                    status: 'approved',
                    customerPhone: q ? q.customer_phone : ''
                };
                fetch(`${API}/calendar/events`, {
                    method: 'POST', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(payload)
                }).catch(e => {});

                // עדכון התאריך בהזמנה
                fetch(`${API}/store/orders/${window.currentActionTargetId}/target-date`, {
                    method: 'PATCH', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ targetDatetime: targetDate })
                }).catch(e=>{});
            }

            // עדכון המטמון המקומי כדי שההעברה תשוקף מיד למשתמש
            if (q) {
                q.status = 'processing';
                q.quote_status = 'approved';
                
                // נוודא שהיא נכנסת למטמון ההזמנות
                if (window.storeOrdersCache) {
                    const existingOrder = window.storeOrdersCache.find(o => String(o.id) === String(q.id));
                    if (!existingOrder) {
                        window.storeOrdersCache.push(q);
                    } else {
                        existingOrder.status = 'processing';
                        existingOrder.quote_status = 'approved';
                    }
                }
            }
            
            showToast('success', 'הצעת המחיר אושרה והועברה לתור ההזמנות בהצלחה!');
            document.getElementById('target-datetime-modal').classList.add('hidden');
            
            // רינדור מחדש של המסכים ללא צורך בהמתנה לקריאת שרת
            if(typeof window.renderStoreQuotes === 'function') window.renderStoreQuotes();
            if(typeof window.renderStoreOrders === 'function') window.renderStoreOrders();
            
            // משיכה שקטה ברקע לאימות
            setTimeout(() => {
                if(typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
                if(typeof window.fetchCalendarData === 'function') window.fetchCalendarData();
            }, 1000);
            
        } else if (window.currentActionType === 'order') {
            const res = await fetch(`${API}/store/orders/${window.currentActionTargetId}/target-date`, {
                method: 'PATCH', headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ targetDatetime: targetDate })
            });
            const data = await res.json();
            if(data.success) {
                showToast('success', 'יעד האספקה / האירוע עודכן בהזמנה!');
                document.getElementById('target-datetime-modal').classList.add('hidden');
                if(typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
            } else {
                showToast('error', data.error || 'שגיאה בעדכון יעד');
            }
        }
    } catch(e) {
        showToast('error', e.message || 'שגיאת תקשורת מול השרת בביצוע ההמרה');
    } finally {
        btn.disabled = false; btn.innerHTML = 'אישור ועדכון';
    }
};

let selectedQuoteItems = {};
let editingQuoteId = null;

window.openEditQuoteModal = function(quoteId) {
    const q = window.storeQuotesCache.find(x => String(x.id) === String(quoteId));
    if (!q) return;

    window.editingQuoteId = quoteId;
    window.selectedQuoteItems = {};

    const rawItems = Array.isArray(q.items) ? q.items : (typeof q.items === 'string' ? JSON.parse(q.items) : []);

    rawItems.forEach(i => {
        if (i.catalogId === null || i.catalogId === 0 || i.catalogId === 999999 || i.is_quote_metadata || i.is_delivery_metadata || (i.name && i.name.startsWith('DELIVERY_META|'))) return;

        let isComplex = false;
        if (i.options_text && i.options_text !== 'null' && i.options_text !== 'undefined') {
            try {
                const p = JSON.parse(i.options_text);
                if (p && p.isComplex) isComplex = true;
            } catch(e) {}
        }

        let strId = String(i.catalogId || i.id || Date.now());
        if (isComplex) {
            strId = strId + '_' + Date.now() + Math.random().toString(36).substr(2, 5);
        }

        window.selectedQuoteItems[strId] = {
            id: strId,
            real_id: i.catalogId,
            name: i.item_name || i.name,
            image_url: i.image_url || '',
            price_at_order: parseFloat(i.price_at_order || i.price || 0),
            quantity: parseFloat(i.quantity) || 1,
            note: i.note || '',
            complex_data: i.options_text || null,
            isComplex: isComplex
        };
    });

    window.openNewQuoteModal(true);

    setTimeout(() => {
        document.getElementById('quote-cust-name').value = q.customer_name || '';
        document.getElementById('quote-cust-phone').value = q.customer_phone || '';

        let userNotes = q.notes || '';
        let introText = '';
        let validity = '14 יום';
        let companyId = localStorage.getItem('ofl_company_id') || '';
        let myCompanyId = localStorage.getItem('ofl_my_company_id') || '';
        let internalNote = '';

        // חיפוש המידע בפורמט החדש (מתוך המטא-דאטה של הפריטים)
        const metaItem = rawItems.find(i => i.is_quote_metadata);
        if (metaItem) {
            try {
                const meta = JSON.parse(metaItem.data);
                if(meta.discount !== undefined) document.getElementById('quote-discount').value = meta.discount;
                if(meta.internalNote) internalNote = meta.internalNote;
                if(meta.introText) introText = meta.introText;
                if(meta.validity) validity = meta.validity;
                if(meta.companyId) companyId = meta.companyId;
                if(meta.myCompanyId) myCompanyId = meta.myCompanyId;
                if(meta.notes) userNotes = meta.notes; // התנאים המשפטיים
            } catch(e) {}
        } else {
            // תאימות לאחור להצעות מחיר ישנות שנוצרו לפני העדכון
            try {
                const parsedNotes = JSON.parse(q.notes);
                userNotes = parsedNotes.notes || '';
                introText = parsedNotes.introText || '';
                validity = parsedNotes.validity || '';
                companyId = parsedNotes.companyId || companyId;
                myCompanyId = parsedNotes.myCompanyId || myCompanyId;
                internalNote = parsedNotes.internalNote || '';
            } catch(e) {}
        }

        userNotes = userNotes.replace('[הצעת מחיר] - הוגשה בקשה לאירוע/פרויקט.', '').trim();

        document.getElementById('quote-notes').value = userNotes;
        if(document.getElementById('quote-intro-text')) document.getElementById('quote-intro-text').value = introText;
        if(document.getElementById('quote-validity')) document.getElementById('quote-validity').value = validity;
        if(document.getElementById('quote-company-id')) document.getElementById('quote-company-id').value = companyId;
        if(document.getElementById('quote-my-company-id')) document.getElementById('quote-my-company-id').value = myCompanyId;
        if(document.getElementById('quote-internal-note')) document.getElementById('quote-internal-note').value = internalNote;

        window.calcQuoteTotal();
        window.renderQuoteSelectedItems();
    }, 100);
};
window.getQuotePresets = function(type) {
    try { return JSON.parse(localStorage.getItem(`ofl_quote_presets_${type}`)) || []; } catch(e) { return []; }
};

window.saveQuotePreset = function(type) {
    const valToSave = getEl(type === 'intro' ? 'quote-intro-text' : 'quote-notes').value.trim();
    if(!valToSave) return showToast('error', 'הטקסט ריק, אין מה לשמור');
    const presets = window.getQuotePresets(type);
    if(!presets.includes(valToSave)) { 
        presets.push(valToSave); 
        localStorage.setItem(`ofl_quote_presets_${type}`, JSON.stringify(presets)); 
        showToast('success', 'נשמר כתבנית לשימוש עתידי!'); 
        window.ensureQuoteHeaders(true); 
    } else {
        showToast('info', 'התבנית הזו כבר שמורה');
    }
};

window.applyQuotePreset = function(type, idx) {
    if(idx === '') return;
    const presets = window.getQuotePresets(type);
    if(presets[idx]) getEl(type === 'intro' ? 'quote-intro-text' : 'quote-notes').value = presets[idx];
};

window.generateQuoteAI = async function(type, btnElement) {
    const custName = val('quote-cust-name') || 'לקוח יקר';
    const query = type === 'intro' 
        ? `כתוב 2 משפטי פתיחה רשמיים, מכובדים ומקצועיים להצעת מחיר עבור הלקוח: ${custName}. העסק השולח: ${currentGroup.name}. חובה: ללא אימוג'ים או אייקונים כלל. החזר אך ורק את המשפטים ללא שום מילת הקדמה מצידך.` 
        : `כתוב 3 סעיפים מפורטים, רשמיים ומקצועיים של תנאי תשלום והערות משפטיות להצעת מחיר (למשל: תוקף ההצעה 14 יום, המחיר אינו כולל מע"מ) עבור העסק: ${currentGroup.name}. חובה: ללא אימוג'ים או אייקונים כלל. החזר אך ורק את הסעיפים, ללא מילות פתיחה וללא סיכום.`;
    
    const targetId = type === 'intro' ? 'quote-intro-text' : 'quote-notes';
    
    const originalHtml = btnElement ? btnElement.innerHTML : '';
    if (btnElement) {
        btnElement.disabled = true;
        btnElement.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> מנסח...';
    }
    
    showToast('info', 'ה-AI מעבד בקשה, המתן מספר שניות...');
    
    try {
        const res = await fetch(`${API}/biz/chat-assistant`, { 
            method: 'POST', headers: {'Content-Type': 'application/json'}, 
            body: JSON.stringify({ 
                query: query, 
                context: JSON.stringify({ role: "מומחה לכתיבת מסמכים עסקיים ומשפטיים. אתה מנסח טקסטים בצורה רשמית, מפורטת ומקצועית בלבד, ללא אימוג'ים וללא שום טקסט מקדים או מסכם." }), 
                groupId: currentGroup.id 
            }) 
        });
        const data = await res.json();
        
        if (data.error === 'BATTERY_EMPTY') {
            handleAIResponseCheck(data);
            return;
        }
        
        if (data.success && data.answer) { 
            let finalOutput = data.answer.replace(/["*]/g, '').trim();
            finalOutput = finalOutput.replace(/^(להלן|הנה|אלו|מצאתי|מצורפים|לבקשתך|הסעיפים).*?:?\n/i, '').trim(); 
            getEl(targetId).value = finalOutput;
            showToast('success', 'הטקסט הושלם בהצלחה!'); 
        } else { 
            showToast('error', data.error || 'אירעה שגיאת AI, נסה שנית'); 
        }
    } catch(e) { 
        showToast('error', 'תקלת רשת מול שרת ה-AI'); 
    } finally {
        if (btnElement) {
            btnElement.disabled = false;
            btnElement.innerHTML = originalHtml;
        }
    }
};

window.ensureQuoteHeaders = function(forceRefresh = false) {
    const introPresets = window.getQuotePresets('intro').map((p,i) => `<option value="${i}">תבנית ${i+1}</option>`).join('');
    const notesPresets = window.getQuotePresets('notes').map((p,i) => `<option value="${i}">תבנית ${i+1}</option>`).join('');

    const introLabel = document.getElementById('quote-intro-text')?.previousElementSibling;
    if(introLabel && (introLabel.tagName === 'LABEL' || forceRefresh)) {
        const wrapper = document.createElement('div');
        wrapper.className = 'flex justify-between items-center mb-1 mt-2';
        wrapper.innerHTML = `<label class="text-[10px] font-bold text-slate-500">טקסט פתיחה:</label>
            <div class="flex gap-1">
                <button type="button" onclick="window.generateQuoteAI('intro', this)" class="text-[9px] bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded shadow-sm hover:bg-purple-100 transition flex items-center gap-1"><i class="fa-solid fa-wand-magic-sparkles"></i> AI</button>
                <select id="sel-preset-intro" onchange="window.applyQuotePreset('intro', this.value)" class="text-[9px] bg-slate-50 border border-slate-200 text-slate-600 rounded px-1 py-0.5 outline-none w-16"><option value="">תבניות...</option>${introPresets}</select>
                <button type="button" onclick="window.saveQuotePreset('intro')" class="text-[9px] bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded shadow-sm hover:bg-blue-100 transition flex items-center gap-1"><i class="fa-solid fa-save"></i> שמור</button>
            </div>`;
        introLabel.replaceWith(wrapper);
    }
    const notesLabel = document.getElementById('quote-notes')?.previousElementSibling;
    if(notesLabel && (notesLabel.tagName === 'LABEL' || forceRefresh)) {
        const wrapper = document.createElement('div');
        wrapper.className = 'flex justify-between items-center mb-1 mt-2';
        wrapper.innerHTML = `<label class="text-[10px] font-bold text-slate-500">הערות ותנאים:</label>
            <div class="flex gap-1">
                <button type="button" onclick="window.generateQuoteAI('notes', this)" class="text-[9px] bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded shadow-sm hover:bg-purple-100 transition flex items-center gap-1"><i class="fa-solid fa-wand-magic-sparkles"></i> AI</button>
                <select id="sel-preset-notes" onchange="window.applyQuotePreset('notes', this.value)" class="text-[9px] bg-slate-50 border border-slate-200 text-slate-600 rounded px-1 py-0.5 outline-none w-16"><option value="">תבניות...</option>${notesPresets}</select>
                <button type="button" onclick="window.saveQuotePreset('notes')" class="text-[9px] bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded shadow-sm hover:bg-blue-100 transition flex items-center gap-1"><i class="fa-solid fa-save"></i> שמור</button>
            </div>`;
        notesLabel.replaceWith(wrapper);
    }
};

window.calcQuoteTotal = function() {
    let total = 0;
    if (window.selectedQuoteItems) {
        Object.values(window.selectedQuoteItems).forEach(item => {
            let rowBasePrice = (parseFloat(item.price_at_order) || 0);
            
            if (item.complex_data) {
                try {
                    const parsed = JSON.parse(item.complex_data);
                    if (parsed.steps) {
                        parsed.steps.forEach(step => {
                            if (step.options) {
                                step.options.forEach(opt => {
                                    if (opt.selected === true || opt.selected === 'true') {
                                        rowBasePrice += (parseFloat(opt.price) || 0) * (parseFloat(opt.qty) || 1);
                                    }
                                });
                            }
                        });
                    }
                } catch(e){}
            }
            
            total += rowBasePrice * (parseFloat(item.quantity) || 0);
        });
    }
    
    const discountStr = document.getElementById('quote-discount') ? document.getElementById('quote-discount').value : '0';
    let discount = parseFloat(discountStr) || 0;
    if (discount > 100) discount = 100;
    if (discount < 0) discount = 0;
    
    const beforeDiscount = total;
    total = total - (total * (discount / 100));
    
    // חישוב מע"מ אם מופעל
    let vatHtml = '';
    const vatSettings = window.getVatSettings();
    if (vatSettings && vatSettings.enabled) {
        const vatRate = vatSettings.rate || 18;
        const totalBeforeVat = total / (1 + (vatRate / 100));
        const vatAmountCalc = total - totalBeforeVat;
        vatHtml = `<div class="text-[10px] text-indigo-400 mt-1">סכום נטו: ₪${totalBeforeVat.toFixed(2)} | מע"מ: ₪${vatAmountCalc.toFixed(2)}</div>`;
    }

    const totalEl = document.getElementById('quote-total-display');
    const beforeEl = document.getElementById('quote-before-discount');
    const vatDisplayEl = document.getElementById('quote-vat-display');
    
    if (totalEl) totalEl.innerText = `₪${total.toFixed(2)}`;
    
    if (beforeEl) {
        if (discount > 0) {
            beforeEl.innerHTML = `<span class="line-through">₪${beforeDiscount.toFixed(2)}</span> (-${discount}%)`;
        } else {
            beforeEl.innerText = '';
        }
    }

    // עדכון או יצירת תצוגת מע"מ מתחת לסך הכל
    if (vatDisplayEl) {
        vatDisplayEl.innerHTML = vatHtml;
    } else if (totalEl && vatHtml) {
        totalEl.insertAdjacentHTML('afterend', `<div id="quote-vat-display" class="font-bold text-left">${vatHtml}</div>`);
    } else if (vatDisplayEl && !vatHtml) {
        vatDisplayEl.innerHTML = '';
    }
};

window.toggleQuoteExpandedView = function() {
    const catCol = document.getElementById('quote-catalog-col');
    const itemsCol = document.getElementById('quote-items-col');
    const btn = document.getElementById('btn-quote-expand');
    if (!catCol || !itemsCol || !btn) return;

    if (catCol.classList.contains('hidden')) {
        catCol.classList.remove('hidden');
        itemsCol.classList.remove('lg:w-full');
        itemsCol.classList.add('lg:w-1/2');
        btn.innerHTML = '<i class="fa-solid fa-expand"></i> תצוגה מורחבת';
    } else {
        catCol.classList.add('hidden');
        itemsCol.classList.remove('lg:w-1/2');
        itemsCol.classList.add('lg:w-full');
        btn.innerHTML = '<i class="fa-solid fa-compress"></i> תצוגה רגילה';
    }
};

