setInterval(() => {
    if(typeof window.applyCustomAILogo === 'function') window.applyCustomAILogo();
}, 5000);
setTimeout(() => { if(typeof window.applyCustomAILogo === 'function') window.applyCustomAILogo(); }, 1000);

