window.loginSliderInterval = null;
window.currentLoginSlideIndex = 0;

window.initPublicConfig = async function() {
    try {
        const res = await fetch(`${API}/system/public-config`);
        const data = await res.json();
        
        if (data.success) {
            // החלפת סמל הדפדפן (Favicon)
            if (data.globalAiLogo) {
                window.currentBizAiLogo = data.globalAiLogo;

                const link = document.querySelector("link[rel~='icon']");
                if (link) link.href = data.globalAiLogo;
                else {
                    const newLink = document.createElement('link');
                    newLink.rel = 'icon'; newLink.href = data.globalAiLogo;
                    document.head.appendChild(newLink);
                }
                document.querySelectorAll("link[rel='shortcut icon'], link[rel='apple-touch-icon']").forEach(l => l.href = data.globalAiLogo);

                // og:image — add if missing, update if exists
                ['og:image','og:image:secure_url'].forEach(prop => {
                    let m = document.querySelector(`meta[property="${prop}"]`);
                    if (!m) { m = document.createElement('meta'); m.setAttribute('property', prop); document.head.appendChild(m); }
                    m.content = data.globalAiLogo;
                });

                // פתרון לתקלת ה"החלפה לשנייה אחת":
                // מכיוון שיש קוד אחר שמרענן את מסך ה-HTML בעת טעינת הדף ודורס את הבועה (pristineHTML),
                // אנו משתמשים ב-setInterval כדי לוודא שהלוגו נשאר מעודכן לנצח ולא מתאפס ל-logo.png.
                setInterval(() => {
                    document.querySelectorAll('img[alt*="FamliAI"], img[alt*="FamilAI"], #ai-assistant-logo-img').forEach(img => {
                        // בדיקת getAttribute מונעת רינדור אינסופי והבהוב של הדפדפן
                        if (img.getAttribute('src') !== data.globalAiLogo) {
                            img.src = data.globalAiLogo;
                        }
                    });
                }, 500);
            }

            // בניית קרוסלת ההתחברות (Login Slider)
            if (data.loginSlides && data.loginSlides.length > 0) {
                const wrapper = document.getElementById('login-slider-wrapper');
                const scroll = document.getElementById('login-slider-scroll');
                const dots = document.getElementById('login-slider-dots');
                const defaultCredit = document.getElementById('login-default-credit');
                
                if (wrapper && scroll && dots && defaultCredit) {
                    defaultCredit.classList.add('hidden');
                    wrapper.classList.remove('hidden');
                    
                    // החלפת ה-auto ב-hidden מעלימה את הפס האפור ומונעת גלילה ידנית
                    scroll.classList.remove('overflow-x-auto');
                    scroll.classList.add('overflow-hidden');
                    scroll.style.overflow = 'hidden';
                    scroll.style.touchAction = 'none'; 
                    
                    let slidesHtml = '';
                    let dotsHtml = '';
                    
                    data.loginSlides.forEach((slide, idx) => {
                        slidesHtml += `
                        <div class="min-w-full w-full h-full shrink-0 snap-center relative flex justify-center items-center">
                            <img src="${slide.image}" class="w-full h-full object-cover z-10 pointer-events-none select-none bg-slate-900">
                        </div>`;
                        dotsHtml += `<button onclick="window.goToLoginSlide(${idx}, ${data.loginSlides.length})" id="login-dot-${idx}" class="rounded-full transition-all duration-300 ${idx === 0 ? 'bg-white w-5 h-2' : 'bg-white/40 hover:bg-white/80 w-2 h-2'} shadow-sm backdrop-blur-sm border border-black/10 z-30 relative"></button>`;
                    });
                    
                    scroll.innerHTML = slidesHtml;
                    dots.innerHTML = data.loginSlides.length > 1 ? dotsHtml : ''; 
                    
                    if (data.loginSlides.length > 1) {
                        window.startLoginAutoScroll(data.loginSlides.length);
                    }
                }
            }
        }
    } catch(e) { console.error('Failed to load public config', e); }
};

window.startLoginAutoScroll = function(total) {
    if (window.loginSliderInterval) clearInterval(window.loginSliderInterval);
    window.loginSliderInterval = setInterval(() => {
        window.currentLoginSlideIndex++;
        if (window.currentLoginSlideIndex >= total) {
            window.currentLoginSlideIndex = 0;
        }
        window.goToLoginSlide(window.currentLoginSlideIndex, total);
    }, 4500); 
};

window.goToLoginSlide = function(index, totalSlides) {
    window.currentLoginSlideIndex = index;
    const scroll = document.getElementById('login-slider-scroll');
    if (scroll) {
        const w = scroll.clientWidth;
        const isRTL = window.getComputedStyle(scroll).direction === 'rtl';
        // החלקה חלקה חכמה באמצעות קוד בלבד, למרות שהגלילה נחסמה למשתמש
        scroll.scrollTo({ left: index * w * (isRTL ? -1 : 1), behavior: 'smooth' });
    }
    
    const dotsDiv = document.getElementById('login-slider-dots');
    const total = totalSlides || (dotsDiv ? dotsDiv.children.length : 0);
    window.updateLoginDots(total);
    
    // איפוס הטיימר לאחר לחיצה ידנית
    if (total > 1) {
        window.startLoginAutoScroll(total);
    }
};

window.updateLoginDots = function(total) {
    for (let i = 0; i < total; i++) {
        const dot = document.getElementById(`login-dot-${i}`);
        if (dot) {
            dot.className = `rounded-full transition-all duration-300 shadow-sm backdrop-blur-sm border border-black/10 z-30 relative ${i === window.currentLoginSlideIndex ? 'bg-white w-5 h-2' : 'bg-white/40 hover:bg-white/80 w-2 h-2'}`;
        }
    }
};

// ── ACTIVITY FEED ──────────────────────────────────────────────
const ACTION_ICONS_BIZ = { finance:'💰', task:'✅', shopping:'🛒', pantry:'📦', business:'🏪', user:'👤' };

async function openActivityPanel() {
  const panel = document.getElementById('activity-panel');
  if (!panel) return;
  panel.classList.remove('hidden');
  if (currentUser?.role === 'ADMIN') {
    const filters = document.getElementById('activity-filters');
    if (filters) filters.classList.remove('hidden');
    const sel = document.getElementById('filter-user');
    if (sel) {
      sel.innerHTML = '<option value="">כל המשתמשים</option>';
      if (membersCache) membersCache.forEach(m => sel.innerHTML += `<option value="${m.id}">${safeStr(m.nickname)}</option>`);
    }
  }
  ['filter-days','filter-type','filter-user'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', loadActivityFeed);
  });
  await loadActivityFeed();
}

function closeActivityPanel() {
  const panel = document.getElementById('activity-panel');
  if (panel) panel.classList.add('hidden');
  const badge = document.getElementById('bell-badge');
  if (badge) badge.classList.add('hidden');
}

async function loadActivityFeed() {
  const days = document.getElementById('filter-days')?.value || 30;
  const type = document.getElementById('filter-type')?.value || 'all';
  const filterUser = document.getElementById('filter-user')?.value || '';
  const list = document.getElementById('activity-list');
  if (!list) return;
  list.innerHTML = '<div class="text-center py-6 text-slate-400 text-sm">טוען...</div>';
  try {
    let url = `${API}/activity?userId=${currentUser.id}&days=${days}`;
    if (type !== 'all') url += `&actionType=${type}`;
    const res = await fetch(url);
    const data = await res.json();
    if (!data.success || !data.activities.length) {
      list.innerHTML = '<div class="text-center py-8 text-slate-400 text-sm">אין פעולות להצגה</div>';
      return;
    }
    let acts = data.activities;
    if (filterUser) acts = acts.filter(a => String(a.user_id) === String(filterUser));
    list.innerHTML = acts.map(a => {
      const icon = ACTION_ICONS_BIZ[a.action_type] || '•';
      const time = new Date(a.created_at).toLocaleString('he-IL', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' });
      const who = a.nickname || a.user_name || 'מערכת';
      return `<div class="bg-slate-50 rounded-xl p-3 border border-slate-100">
        <div class="flex items-start gap-2">
          <span class="text-lg flex-shrink-0">${icon}</span>
          <div class="flex-1 min-w-0">
            <p class="text-sm font-medium text-slate-700 leading-snug">${safeStr(a.description)}</p>
            <p class="text-xs text-slate-400 mt-1">${safeStr(who)} · ${time}</p>
          </div>
        </div>
      </div>`;
    }).join('');
  } catch(e) { list.innerHTML = '<div class="text-center py-8 text-red-400 text-sm">שגיאה בטעינה</div>'; }
}

async function refreshBellBadge() {
  if (!currentUser) return;
  try {
    const res = await fetch(`${API}/activity?userId=${currentUser.id}&days=1&limit=1`);
    const data = await res.json();
    const badge = document.getElementById('bell-badge');
    if (!badge) return;
    const count = data.unreadCount || 0;
    if (count > 0) {
      badge.textContent = count > 99 ? '99+' : count;
      badge.classList.remove('hidden');
    } else {
      badge.classList.add('hidden');
    }
  } catch(e) {}
}

// ── QUICK ACCESS TILES (BUSINESS) ─────────────────────────────
function renderQuickTiles() {
  const container = document.getElementById('quick-tiles');
  if (!container) return;
  const storeOrderCount = (storeOrdersCache || []).filter(o => o.status === 'pending' || o.status === 'new').length;
  const tiles = [
    { fa:'fa-clock-rotate-left', label:'נוכחות',        badge: null,            tab:'timeclock', bg:'#f8fafc', grad:'linear-gradient(135deg,#64748b,#334155)', badge_bg:'#475569' },
    { fa:'fa-calendar-days',     label:'משמרות',         badge: null,            tab:'shifts',    bg:'#eff6ff', grad:'linear-gradient(135deg,#60a5fa,#4338ca)', badge_bg:'#3730a3' },
    { fa:'fa-calendar-check',    label:'יומן ותורים',    badge: null,            tab:'calendar',  bg:'#faf5ff', grad:'linear-gradient(135deg,#a78bfa,#7c3aed)', badge_bg:'#6d28d9' },
    { fa:'fa-bag-shopping',      label:'מכירות וחנות',   badge: storeOrderCount, tab:'sales',     bg:'#fffbeb', grad:'linear-gradient(135deg,#fbbf24,#d97706)', badge_bg:'#b45309' },
    { fa:'fa-cart-arrow-down',   label:'רכש',           badge: null,            tab:'shop',      bg:'#ecfdf5', grad:'linear-gradient(135deg,#34d399,#0f766e)', badge_bg:'#0d9488' },
    { fa:'fa-chart-line',        label:'כספים',          badge: null,            tab:'bank',      bg:'#fff1f2', grad:'linear-gradient(135deg,#f43f5e,#be123c)', badge_bg:'#9f1239' },
  ];
  container.innerHTML = tiles.map(t => `
    <button onclick="switchTab('${t.tab}')"
      style="background:${t.bg};border:1.5px solid rgba(0,0,0,0.06)"
      class="relative rounded-2xl p-3.5 flex flex-col items-center gap-2 shadow-sm hover:shadow-lg hover:scale-[1.04] active:scale-95 transition-all duration-200 cursor-pointer">
      <div style="background:${t.grad}" class="w-11 h-11 rounded-xl flex items-center justify-center shadow-md mb-0.5">
        <i class="fa-solid ${t.fa} text-white text-lg"></i>
      </div>
      <span class="text-[11px] font-bold text-slate-600 text-center leading-tight">${t.label}</span>
      ${t.badge !== null && t.badge > 0 ? `<span style="background:${t.badge_bg}" class="absolute -top-1.5 -right-1.5 text-white text-[9px] font-black rounded-full min-w-[18px] h-[18px] flex items-center justify-center px-1 shadow-md">${t.badge}</span>` : ''}
    </button>
  `).join('');
}

// במקום DOMContentLoaded אנו ממתינים שכל ה-HTML כולל ההזרקות הדינמיות יסיים, ורק אז שולפים את נתוני המיתוג
window.addEventListener('load', () => {
    setTimeout(() => {
        window.initPublicConfig();
    }, 200);
});

// ═══════════════════════════════════════════════════════════════
// KIOSK SELF-ORDER SYSTEM
// ═══════════════════════════════════════════════════════════════

let kioskCart = [];           // [{id,name,price,qty}]
let kioskCustomer = {};       // {name,phone}
let kioskCurrentStep = 1;
let kioskCatalog = [];
let kioskGroupId = null;
let kioskPasswordCache = null;
let kioskHoldTimer = null;
let kioskHoldInterval = null;
let kioskCountdownTimer = null;
let kioskCurrentCat = 'all';

async function openKioskMode() {
    if (!currentGroup) return showToast('יש להתחבר קודם', 'warning');
    kioskGroupId = currentGroup.id;

    // Fix 1: Exit POS fullscreen before opening kiosk
    const posContainer = document.getElementById('content-pos');
    if (posContainer && posContainer.classList.contains('pos-is-fullscreen')) {
        try { window.togglePOSFullscreen(false); } catch(e) {}
    }

    kioskReset(true);
    const overlay = document.getElementById('kiosk-overlay');
    overlay.classList.remove('hidden');

    // Fix 2: Request browser fullscreen for kiosk
    try {
        const el = document.documentElement;
        if (el.requestFullscreen) await el.requestFullscreen();
        else if (el.webkitRequestFullscreen) await el.webkitRequestFullscreen();
    } catch(e) {}

    // Load catalog & settings
    try {
        const res = await fetch(`${API}/store/kiosk-settings/${kioskGroupId}`);
        const data = await res.json();
        if (data.success) {
            kioskCatalog = data.catalog || [];
            const storeName = data.settings?.store_name || data.storeName || currentGroup.name || 'הקיוסק שלנו';
            document.getElementById('kiosk-store-name').textContent = storeName;
            if (data.settings?.logo_url) {
                document.getElementById('kiosk-logo-img').src = data.settings.logo_url;
                document.getElementById('kiosk-logo-img').style.display = '';
            }
            kioskPasswordCache = data.settings?.kiosk_password || '1234';
        }
    } catch(e) {
        kioskCatalog = (storeCatalogCache || []).filter(i => i.is_available);
        kioskPasswordCache = '1234';
    }
    kioskShowStep(1);
}

function closeKioskMode() {
    // Fix 2: Exit browser fullscreen on kiosk close
    try {
        if (document.fullscreenElement) {
            if (document.exitFullscreen) document.exitFullscreen();
            else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
        }
    } catch(e) {}
    window.kioskModeCapture = false;
    document.getElementById('kiosk-overlay').classList.add('hidden');
    document.getElementById('kiosk-exit-modal').classList.add('hidden');
    if (kioskCountdownTimer) clearInterval(kioskCountdownTimer);
    kioskCart = [];
    kioskCustomer = {};
}

function kioskReset(skipStepShow) {
    kioskCart = [];
    kioskCustomer = {};
    kioskCurrentCat = 'all';
    document.getElementById('kiosk-name').value = '';
    document.getElementById('kiosk-phone').value = '';
    document.getElementById('kiosk-notes').value = '';
    if (kioskCountdownTimer) { clearInterval(kioskCountdownTimer); kioskCountdownTimer = null; }
    if (!skipStepShow) kioskShowStep(1);
}

function kioskShowStep(n) {
    kioskCurrentStep = n;
    [1,2,3,4].forEach(i => {
        const el = document.getElementById(`kiosk-step-${i}`);
        if (!el) return;
        if (i === n) el.classList.remove('hidden');
        else el.classList.add('hidden');
    });
    // step dots
    document.querySelectorAll('.kiosk-dot').forEach(d => {
        const s = parseInt(d.dataset.step);
        d.style.background = s === n ? '#f59e0b' : s < n ? '#10b981' : 'rgba(255,255,255,0.2)';
    });
    const labels = ['זיהוי', 'בחירת מוצרים', 'סיכום הזמנה', 'בוצע!'];
    document.getElementById('kiosk-step-label').textContent = labels[n-1] || '';
}

async function kioskNext1() {
    const name = document.getElementById('kiosk-name').value.trim();
    const phone = document.getElementById('kiosk-phone').value.trim().replace(/\D/g,'');
    if (!name) { document.getElementById('kiosk-name').focus(); return; }
    kioskCustomer = { name, phone };

    if (phone) {
        try {
            const res = await fetch(`${API}/store/kiosk-lookup`, {
                method:'POST', headers:{'Content-Type':'application/json'},
                body: JSON.stringify({ groupId: kioskGroupId, phone, name })
            });
            const data = await res.json();
            if (data.success && data.customer && !data.isNew) {
                // Returning customer — update name from CRM record
                kioskCustomer.name = data.customer.name || name;
            }
        } catch(e) {}
    }
    kioskBuildCatalog();
    kioskShowStep(2);
}

// Auto-lookup when phone field has enough digits
async function kioskPhoneLookup() {
    const phone = (document.getElementById('kiosk-phone')?.value || '').replace(/\D/g,'');
    const statusEl = document.getElementById('kiosk-lookup-status');
    if (!statusEl) return;
    if (phone.length < 9) { statusEl.innerHTML = ''; return; }
    statusEl.innerHTML = `<span class="text-white/50 text-sm animate-pulse">מחפש...</span>`;
    try {
        const res = await fetch(`${API}/store/kiosk-lookup`, {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ groupId: kioskGroupId, phone, name: 'לקוח' })
        });
        const data = await res.json();
        if (data.success && data.customer && !data.isNew) {
            const c = data.customer;
            const visits = data.orderCount || 0;
            // Pre-fill name
            document.getElementById('kiosk-name').value = c.name || '';
            statusEl.innerHTML = `
                <div class="flex items-center gap-3 bg-white/10 border border-white/20 rounded-2xl px-5 py-3 text-right">
                    <div class="w-10 h-10 rounded-full flex items-center justify-center text-2xl shrink-0" style="background:linear-gradient(135deg,#10b981,#0d9488)">😊</div>
                    <div>
                        <p class="text-white font-bold text-base">שלום ${c.name}! טוב שחזרת</p>
                        <p class="text-white/50 text-xs">${visits > 0 ? `${visits} ביקורים קודמים` : 'ביקור ראשון שלך בקיוסק'}</p>
                    </div>
                </div>`;
        } else {
            statusEl.innerHTML = `<p class="text-white/40 text-sm text-center">לקוח חדש — נשמח להכיר 👋</p>`;
        }
    } catch(e) { statusEl.innerHTML = ''; }
}

function kioskSkipIdentify() {
    kioskCustomer = { name: 'לקוח', phone: '' };
    kioskBuildCatalog();
    kioskShowStep(2);
}

function kioskBuildCatalog() {
    // Build category tabs
    const cats = ['all', ...new Set((kioskCatalog).map(p => p.category || 'כללי').filter(Boolean))];
    const catsEl = document.getElementById('kiosk-cats');
    catsEl.innerHTML = cats.map(c => `
        <button class="kiosk-cat-tab flex-shrink-0 px-5 py-2.5 rounded-full text-white/70 text-sm font-bold hover:text-white transition ${c === kioskCurrentCat ? 'active' : ''}"
                style="background:rgba(255,255,255,0.08)"
                onclick="kioskSetCat('${c}')">
            ${c === 'all' ? 'הכל' : c}
        </button>`).join('');
    kioskRenderGrid();
}

function kioskSetCat(cat) {
    kioskCurrentCat = cat;
    document.querySelectorAll('.kiosk-cat-tab').forEach(b => {
        b.classList.toggle('active', b.textContent.trim() === (cat === 'all' ? 'הכל' : cat));
    });
    kioskRenderGrid();
}

function kioskRenderGrid() {
    const filtered = kioskCurrentCat === 'all'
        ? kioskCatalog
        : kioskCatalog.filter(p => (p.category || 'כללי') === kioskCurrentCat);

    document.getElementById('kiosk-catalog-grid').innerHTML = filtered.map(p => {
        const inCart = kioskCart.find(c => c.id === p.id);
        const qty = inCart ? inCart.qty : 0;
        return `
        <button class="kiosk-product-btn relative bg-white/10 border border-white/10 rounded-2xl p-4 flex flex-col items-center gap-2 hover:border-amber-400/50 hover:bg-white/15 transition"
                onclick="kioskAddItem(${p.id},'${(p.name||'').replace(/'/g,"\\'")}',${p.price})">
            ${p.image_url ? `<img src="${p.image_url}" class="w-20 h-20 object-cover rounded-xl mb-1">` :
              `<div class="w-20 h-20 rounded-xl flex items-center justify-center text-4xl mb-1" style="background:rgba(255,255,255,0.08)">🍽️</div>`}
            ${p.badge_text ? `<span class="absolute top-2 right-2 text-[10px] font-black px-2 py-0.5 rounded-full text-white" style="background:#ef4444">${p.badge_text}</span>` : ''}
            <p class="text-white font-bold text-sm text-center leading-tight">${p.name}</p>
            <p class="text-amber-400 font-black text-lg">₪${parseFloat(p.price).toFixed(2)}</p>
            ${qty > 0 ? `<span class="absolute -top-2 -left-2 w-7 h-7 rounded-full flex items-center justify-center text-xs font-black text-slate-900" style="background:#f59e0b">${qty}</span>` : ''}
        </button>`;
    }).join('');
}

function kioskAddItem(id, name, price) {
    const p = kioskCatalog.find(c => c.id === id);
    if (p) {
        // Try parsing options_text first
        if (p.options_text && p.options_text.length > 10) {
            try {
                const parsed = JSON.parse(p.options_text);
                if (parsed && (parsed.isBundle || parsed.isComplex || parsed.isPizza || Array.isArray(parsed))) {
                    window.kioskModeCapture = true;
                    window.currentPOSProduct = p;
                    if (parsed.isPizza) { window.openPOSPizzaModal(p, parsed); }
                    else if (parsed.isBundle || parsed.isComplex) { window.openPOSBundleModal(p, parsed); }
                    else if (Array.isArray(parsed)) { window.openPOSModifiersModal(p, parsed); }
                    return;
                }
            } catch(e) {}
        }
        // Fallback: product_type based detection
        const pt = p.product_type || '';
        if (pt === 'pizza_builder') {
            window.kioskModeCapture = true;
            window.currentPOSProduct = p;
            let pd = { isPizza: true, toppings: [] };
            try { pd = JSON.parse(p.options_text) || pd; } catch(e) {}
            window.openPOSPizzaModal(p, pd);
            return;
        }
        if (pt === 'bundle') {
            window.kioskModeCapture = true;
            window.currentPOSProduct = p;
            let bd = { isBundle: true, steps: [] };
            try { bd = JSON.parse(p.options_text) || bd; } catch(e) {}
            window.openPOSBundleModal(p, bd);
            return;
        }
    }
    const existing = kioskCart.find(c => c.id === id && !c.modifiers);
    if (existing) {
        existing.qty++;
    } else {
        kioskCart.push({ id, name, price: parseFloat(price), qty: 1, modifiers: null });
    }
    kioskUpdateCartBar();
    kioskRenderGrid();
}

function kioskUpdateCartBar() {
    const total = kioskCart.reduce((s,i) => s + i.price * i.qty, 0);
    const count = kioskCart.reduce((s,i) => s + i.qty, 0);
    document.getElementById('kiosk-cart-count').textContent = count;
    document.getElementById('kiosk-cart-total').textContent = total.toFixed(2);
}

function kioskGoStep3() {
    if (!kioskCart.length) { showToast('הוסיפו לפחות מוצר אחד', 'warning'); return; }
    const total = kioskCart.reduce((s,i) => s + i.price * i.qty, 0);
    document.getElementById('kiosk-total-confirm').textContent = total.toFixed(2);

    const listEl = document.getElementById('kiosk-cart-list');
    listEl.innerHTML = kioskCart.map((item, idx) => {
        const modTxt = item.modifiers && item.modifiers.length
            ? `<div class="flex flex-wrap gap-1 mt-1">${item.modifiers.map(m=>`<span class="text-[11px] bg-white/10 text-white/70 px-2 py-0.5 rounded-full">${m.name||m}</span>`).join('')}</div>`
            : '';
        return `
        <div class="kiosk-cart-item flex items-center gap-4 py-3 px-2">
            <div class="flex-1 min-w-0">
                <p class="text-white font-bold leading-tight">${item.name}</p>
                ${modTxt}
                <p class="text-white/50 text-sm mt-0.5">₪${item.price.toFixed(2)} × ${item.qty}</p>
            </div>
            <div class="flex items-center gap-3 shrink-0">
                <button onclick="kioskCartQty(${idx},-1)" class="w-9 h-9 rounded-full flex items-center justify-center text-white font-black text-xl" style="background:rgba(255,255,255,0.1)">−</button>
                <span class="text-white font-black text-lg w-6 text-center">${item.qty}</span>
                <button onclick="kioskCartQty(${idx},1)"  class="w-9 h-9 rounded-full flex items-center justify-center text-white font-black text-xl" style="background:rgba(255,255,255,0.1)">+</button>
            </div>
            <p class="text-amber-400 font-black text-lg min-w-[70px] text-left shrink-0">₪${(item.price*item.qty).toFixed(2)}</p>
        </div>`;
    }).join('') + `
        <div class="flex justify-between items-center pt-4 px-2 mt-2 border-t border-white/10">
            <span class="text-white/60 font-bold text-base">סה"כ</span>
            <span class="text-white font-black text-2xl">₪${total.toFixed(2)}</span>
        </div>`;
    kioskShowStep(3);
}

function kioskCartQty(idx, delta) {
    kioskCart[idx].qty += delta;
    if (kioskCart[idx].qty <= 0) kioskCart.splice(idx, 1);
    if (!kioskCart.length) { kioskShowStep(2); return; }
    kioskUpdateCartBar();
    kioskGoStep3();
}

function kioskBack(fromStep) {
    kioskShowStep(fromStep - 1);
    if (fromStep - 1 === 2) kioskRenderGrid();
}

async function kioskSubmitOrder() {
    const total = kioskCart.reduce((s,i) => s + i.price * i.qty, 0);
    const notes = document.getElementById('kiosk-notes').value;
    const btn = document.querySelector('#kiosk-step-3 button[onclick="kioskSubmitOrder()"]');
    if (btn) btn.disabled = true;

    try {
        const res = await fetch(`${API}/store/kiosk-order`, {
            method: 'POST', headers: {'Content-Type':'application/json'},
            body: JSON.stringify({
                groupId: kioskGroupId,
                customerName: kioskCustomer.name,
                customerPhone: kioskCustomer.phone,
                items: kioskCart.map(i => ({ id:i.id, name:i.name, price:i.price, qty:i.qty, modifiers: i.modifiers || [] })),
                notes,
                total
            })
        });
        const data = await res.json();
        if (data.success) {
            document.getElementById('kiosk-order-id-display').textContent = `הזמנה מספר #${data.orderId}`;
            // Refresh orders management so it appears immediately
            setTimeout(() => { try { if(typeof window.fetchStoreOrders==='function') window.fetchStoreOrders(); } catch(e){} }, 1000);
            kioskShowStep(4);
            let countdown = 10;
            document.getElementById('kiosk-countdown').textContent = countdown;
            kioskCountdownTimer = setInterval(() => {
                countdown--;
                document.getElementById('kiosk-countdown').textContent = countdown;
                if (countdown <= 0) { clearInterval(kioskCountdownTimer); kioskReset(); }
            }, 1000);
        } else {
            showToast(data.error || 'שגיאה בשליחת ההזמנה', 'error');
            if (btn) btn.disabled = false;
        }
    } catch(e) {
        showToast('שגיאת תקשורת', 'error');
        if (btn) btn.disabled = false;
    }
}

// ── EXIT HOLD (long-press logo 3 seconds) ─────────────────────
const KIOSK_HOLD_MS = 3000;

function startKioskHold(e) {
    if (e) e.preventDefault();
    const arc = document.getElementById('kiosk-hold-arc');
    const ring = document.getElementById('kiosk-hold-ring');
    if (ring) ring.classList.remove('hidden');
    let elapsed = 0;
    const TOTAL = KIOSK_HOLD_MS;
    const INTERVAL = 80;
    const CIRC = 144.5;
    kioskHoldInterval = setInterval(() => {
        elapsed += INTERVAL;
        const pct = Math.min(elapsed / TOTAL, 1);
        if (arc) arc.style.strokeDashoffset = CIRC * (1 - pct);
        if (pct >= 1) {
            cancelKioskHold();
            showKioskExitModal();
        }
    }, INTERVAL);
}

function cancelKioskHold() {
    if (kioskHoldInterval) { clearInterval(kioskHoldInterval); kioskHoldInterval = null; }
    const arc = document.getElementById('kiosk-hold-arc');
    const ring = document.getElementById('kiosk-hold-ring');
    if (arc) arc.style.strokeDashoffset = '144.5';
    if (ring) ring.classList.add('hidden');
}

function showKioskExitModal() {
    document.getElementById('kiosk-exit-password').value = '';
    document.getElementById('kiosk-exit-error').classList.add('hidden');
    document.getElementById('kiosk-exit-modal').classList.remove('hidden');
    setTimeout(() => document.getElementById('kiosk-exit-password').focus(), 100);
}

async function confirmKioskExit() {
    const entered = document.getElementById('kiosk-exit-password').value;
    // Fetch password if not cached
    if (!kioskPasswordCache) {
        try {
            const r = await fetch(`${API}/store/kiosk-password/${kioskGroupId}`);
            const d = await r.json();
            kioskPasswordCache = d.password || '1234';
        } catch(e) { kioskPasswordCache = '1234'; }
    }
    if (entered === kioskPasswordCache) {
        closeKioskMode();
    } else {
        document.getElementById('kiosk-exit-error').classList.remove('hidden');
        document.getElementById('kiosk-exit-password').value = '';
        document.getElementById('kiosk-exit-password').focus();
    }
}

async function saveKioskPassword() {
    const password = (document.getElementById('kiosk-password-input')?.value || '').trim();
    if (!password) return showToast('יש להזין סיסמה', 'warning');
    try {
        const res = await fetch(`${API}/store/kiosk-password`, {
            method: 'PUT', headers: {'Content-Type':'application/json'},
            body: JSON.stringify({ groupId: currentGroup.id, password })
        });
        const data = await res.json();
        if (data.success) {
            kioskPasswordCache = password;
            showToast('success', 'סיסמת קיוסק נשמרה!');
        } else {
            showToast('error', data.error || 'שגיאה בשמירה');
        }
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
}
